import React, { useState } from 'react';
import { Link } from 'gatsby';
import './Login.css';
import * as Dialog from '@radix-ui/react-dialog';
import './RadixDialog.css';
import { signInWithEmail, signUpWithEmail } from '../../../hooks/useAuthService';

function Login() {
  const [activeTab, setActiveTab] = useState('login');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [registrationData, setRegistrationData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    password: '',
    confirmPassword: '',
    dateOfBirth: '',
    gender: '',
    agreeToTerms: true
  });
  
  const resetError = () => setError(null);

  const handleLogin = async (e) => {
    e.preventDefault();
    resetError();

    if (!loginData.email || !loginData.password) {
      setError('Please fill in all fields');
      return;
    }

    setIsLoading(true);
    try {
      const { data, error: authError } = await signInWithEmail(loginData.email, loginData.password);
      if (authError) throw authError;

      setIsLoading(false);
      if (data) console.log('Login successful:', data);
    } catch (error) {
      setIsLoading(false);
      console.error('Error during login:', error);
      switch (error.message) {
        case 'Invalid login credentials':
          setError('Invalid email or password. Please try again.');
          break;
        case 'Email not confirmed':
          setError('Please verify your email before logging in.');
          break;
        case 'Too many requests':
          setError('Too many login attempts. Please try again later.');
          break;
        default:
          setError('Login failed. Please try again.');
      }
    }
  };

  const handleRegistration = async (e) => {
    e.preventDefault();
    resetError();

    if (registrationData.password !== registrationData.confirmPassword) {
      setError('Passwords do not match!');
      return;
    }

    setIsLoading(true);
    try {
      const { data, error: authError } = await signUpWithEmail(
        registrationData.email,
        registrationData.password,
        registrationData.firstName,
        registrationData.lastName
      );

      setIsLoading(false);
      if (authError) throw authError;

      if (data?.user?.identities?.length === 0) {
        setError('This email is already registered. Try logging in instead.');
        return;
      }

      if (data) {
        console.log('Registration successful:', data);
        setActiveTab('login');
        alert('Registration successful! Please check your email to verify your account.');
      }
    } catch (error) {
      setIsLoading(false);
      console.error('Error during registration:', error);
      switch (error.message) {
        case 'User already registered':
          setError('This email is already registered. Please login instead.');
          break;
        case 'Password should be at least 6 characters':
          setError('Password must be at least 6 characters long.');
          break;
        case 'Invalid email':
        case 'Unable to validate email address: invalid format':
          setError('Please enter a valid email address.');
          break;
        default:
          setError('Registration failed. Please try again.');
      }
    }
  };

  const handleLoginInputChange = (e) => {
    resetError();
    setLoginData({ ...loginData, [e.target.name]: e.target.value });
  };

  const handleRegistrationInputChange = (e) => {
    resetError();
    const { name, value, type, checked } = e.target;
    setRegistrationData({ ...registrationData, [name]: type === 'checkbox' ? checked : value });
  };

  return (
    <div className="login-container-main">
      <Dialog.Root>
        <Dialog.Trigger asChild>
          <button className="dialog-button">Login</button>
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Overlay className="dialog-overlay" style={{ backgroundColor : '', position : 'absolute', zIndex : 9999 }}>
            
            <Dialog.Content className="dialog-content" style={{ overflow: 'auto', maxHeight: '90vh' }}>
            <div className="login-card container">
              <Dialog.Close asChild>
                <button className="dialog-close-button" onClick={resetError}>🗙</button>
              </Dialog.Close>

              {/* Left Section */}
              <div className="login-left">
                <div className="medical-content">
                  <div className="decorative-star floating-element">★</div>
                  <h2 className="medical-title">
                    Get Ready for Back to School — 
                    <span className="highlight"> Easy Online Ordering.</span>
                  </h2>

                  <div className="doctor-image-container">
                    <img
                      src="/Images/header/Outsources_3.svg"
                      alt="Supplies Delivery"
                      className="doctor-image"
                    />
                    <div className="stats-badge">
                      <div className="stat-item">
                        <span className="stat-icon">📦</span>
                        <span className="stat-text">Items Shipped Nationally</span>
                      </div>
                      <div className="stat-item recovery">
                        <span className="stat-icon">💯</span>
                        <span className="stat-text">Parent Satisfaction</span>
                      </div>
                    </div>
                  </div>

                  <div className="decorative-star-2 floating-element">★</div>
                </div>
              </div>

              {/* Right Section */}
              <div className="login-right">
                <div className="login-form-container">
                  {error && (
                    <div className="error-message">
                      {error}
                      <button onClick={resetError} className="error-close-button">×</button>
                    </div>
                  )}

                  <div className="patient-tabs">
                    <button className={`tab ${activeTab === 'login' ? 'active' : ''}`} onClick={() => { resetError(); setActiveTab('login'); }}>
                      Login
                    </button>
                    <button className={`tab ${activeTab === 'registration' ? 'active' : ''}`} onClick={() => { resetError(); setActiveTab('registration'); }}>
                      Registration
                    </button>
                  </div>

                  {/* Login Form */}
                  {activeTab === 'login' && (
                    <form className="login-form" onSubmit={handleLogin}>
                      <h3 className="form-title">🎒 Log In to View Your Order</h3>
                      <p className="form-subtitle">Secure, quick, and easy</p>

                      <div className="input-group">
                        <label htmlFor="email-login">Email</label>
                        <input type="email" id="email-login" name="email" value={loginData.email} onChange={handleLoginInputChange} placeholder="Enter your email" required />
                      </div>

                      <div className="input-group">
                        <label htmlFor="password">Password</label>
                        <div className="password-input-container">
                          <input type={showPassword ? 'text' : 'password'} id="password" name="password" value={loginData.password} onChange={handleLoginInputChange} placeholder="••••••••" required />
                          <button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)}>{showPassword ? '👁️' : '👁️‍🗨️'}</button>
                        </div>
                      </div>

                      <Link to="/reset-password" className="reset-password-link">Reset Password</Link>

                      <button type="submit" className={`login-button ${isLoading ? 'loading' : ''}`} disabled={isLoading}>
                        {isLoading ? <span className="loading-spinner"></span> : 'Login'}
                      </button>
                      <button type="button" className="login-code-button">Login With Code</button>
                    </form>
                  )}

                  {/* Registration Form */}
                  {activeTab === 'registration' && (
                    <form className="login-form registration-form" onSubmit={handleRegistration}>
                      <h3 className="form-title">Create your account</h3>
                      <p className="form-subtitle">Join thousands of happy parents</p>

                      <div className="form-row">
                        <div className="input-group half-width">
                          <label htmlFor="firstName">First Name</label>
                          <input type="text" id="firstName" name="firstName" value={registrationData.firstName} onChange={handleRegistrationInputChange} placeholder="Enter first name" required />
                        </div>
                        <div className="input-group half-width">
                          <label htmlFor="lastName">Last Name</label>
                          <input type="text" id="lastName" name="lastName" value={registrationData.lastName} onChange={handleRegistrationInputChange} placeholder="Enter last name" required />
                        </div>
                      </div>

                      <div className="input-group">
                        <label htmlFor="regEmail">Email Address</label>
                        <input type="email" id="regEmail" name="email" value={registrationData.email} onChange={handleRegistrationInputChange} placeholder="Enter your email" required />
                      </div>

                      <div className="input-group">
                        <label htmlFor="regPassword">Password</label>
                        <input type={showPassword ? 'text' : 'password'} id="regPassword" name="password" value={registrationData.password} onChange={handleRegistrationInputChange} placeholder="Create a strong password (min 6 chars)" required minLength="6" />
                      </div>

                      <div className="input-group">
                        <label htmlFor="confirmPassword">Confirm Password</label>
                        <input type={showConfirmPassword ? 'text' : 'password'} id="confirmPassword" name="confirmPassword" value={registrationData.confirmPassword} onChange={handleRegistrationInputChange} placeholder="Confirm your password" required minLength="6" />
                      </div>

                      <button type="submit" className={`login-button ${isLoading ? 'loading' : ''}`} disabled={isLoading}>
                        {isLoading ? <span className="loading-spinner"></span> : 'Create Account'}
                      </button>

                      <p className="login-prompt">
                        Already have an account?
                        <button type="button" className="switch-tab-button" onClick={() => { resetError(); setActiveTab('login'); }}>Login here</button>
                      </p>
                    </form>
                  )}
                </div>
              </div>
            </div>
          </Dialog.Content>
          </Dialog.Overlay>
          
        </Dialog.Portal>
      </Dialog.Root>
    </div>
  );
}

export default Login;
